/**
 * Generated dedicated Q&A pages.
 *
 * Every theory page that has a card deck gets a companion `<page>-qa.md` route
 * (e.g. docs/docker/dockerfile.md -> docs/docker/dockerfile-qa.md). Authors
 * write only the theory page and its cards; the Q&A route is produced here so
 * it can never drift and needs no per-page maintenance.
 *
 * Files carry a marker comment and are regenerated every build: any stale
 * `-qa.md` whose theory page or cards went away is removed. Generated files are
 * git-ignored.
 */

const fs = require('fs');
const path = require('path');

const { DOCS_DIR } = require('./content-paths');

/** Identifies a file this module owns, so cleanup never touches hand-written docs. */
const MARKER = '<!-- @generated by scripts/lib/qa-pages.js -->';

/** Suffix that turns a theory doc id into its Q&A doc id. */
const QA_SUFFIX = '-qa';

/**
 * Read the `title` from a markdown file's YAML frontmatter.
 *
 * @param {string} filePath
 * @returns {string|null}
 */
function readFrontmatterValue(filePath, key) {
  let head;
  try {
    head = fs.readFileSync(filePath, 'utf8').slice(0, 1000);
  } catch {
    return null;
  }
  if (!head.startsWith('---')) return null;
  const end = head.indexOf('\n---', 3);
  if (end === -1) return null;
  const match = head
    .slice(0, end)
    .match(new RegExp(`^${key}:\\s*(.+?)\\s*$`, 'm'));
  if (!match) return null;
  return match[1].replace(/^['"]|['"]$/g, '');
}

function readFrontmatterTitle(filePath) {
  return readFrontmatterValue(filePath, 'title');
}

/**
 * Absolute path to the theory markdown for a topic/page, or null if none.
 *
 * @param {string} topic
 * @param {string} page Page path within the topic (POSIX separators).
 * @returns {string|null}
 */
function theoryFileFor(topic, page) {
  const file = path.join(DOCS_DIR, topic, ...page.split('/')) + '.md';
  return fs.existsSync(file) ? file : null;
}

/**
 * The Q&A page body.
 *
 * @param {object} args
 * @param {string} args.title Theory page title.
 * @param {string} args.topic
 * @param {string} args.page
 * @param {string} args.sidebar displayed_sidebar value, copied from the theory page's topic.
 * @returns {string}
 */
function renderQaPage({ title, topic, page, sidebar }) {
  return `---
title: ${title} — Practice
displayed_sidebar: ${sidebar}
sidebar_class_name: hidden
description: Active-recall questions for the ${title} theory page
---

${MARKER}

import TopicQA from '@site/src/components/TopicQA';

<TopicQA topic="${topic}" page="${page}" />
`;
}

/**
 * Read a theory page's displayed_sidebar, falling back to `${topic}Sidebar`.
 *
 * @param {string} theoryFile
 * @param {string} topic
 * @returns {string}
 */
function sidebarFor(theoryFile, topic) {
  const head = fs.readFileSync(theoryFile, 'utf8').slice(0, 1000);
  const match = head.match(/^displayed_sidebar:\s*(.+?)\s*$/m);
  return match ? match[1] : `${topic}Sidebar`;
}

/**
 * Remove every generated Q&A page under docs/. Identified by the marker, so a
 * hand-written `-qa.md` (if one ever existed) is left untouched.
 */
function cleanGeneratedQaPages(dir = DOCS_DIR) {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      cleanGeneratedQaPages(full);
    } else if (entry.name.endsWith(`${QA_SUFFIX}.md`)) {
      try {
        if (fs.readFileSync(full, 'utf8').includes(MARKER)) fs.unlinkSync(full);
      } catch {
        // Unreadable file: leave it rather than risk deleting something else.
      }
    }
  }
}

/**
 * Generate a Q&A companion page for every (topic, page) that has cards and a
 * theory page. Stale generated pages are cleared first.
 *
 * @param {Map<string, object[]>} byTopic Cards grouped by topic (from the build).
 * @returns {number} Count of pages written.
 */
function generateQaPages(byTopic) {
  cleanGeneratedQaPages();

  let written = 0;
  for (const [topic, cards] of byTopic) {
    const pages = new Set(cards.map((c) => c.page));
    for (const page of pages) {
      if (!page) continue;
      const theoryFile = theoryFileFor(topic, page);
      if (!theoryFile) continue;

      const title = readFrontmatterTitle(theoryFile) || page;
      const sidebar = sidebarFor(theoryFile, topic);
      const outFile =
        path.join(DOCS_DIR, topic, ...page.split('/')) + `${QA_SUFFIX}.md`;

      fs.writeFileSync(
        outFile,
        renderQaPage({ title, topic, page, sidebar })
      );
      written += 1;
    }
  }
  return written;
}

module.exports = { generateQaPages, cleanGeneratedQaPages };
